  1 | /**
  2 |  * 🦙 Llama Player — useTauri Hook
  3 |  *
  4 |  * Hook React para acessar funcionalidades nativas do Tauri:
  5 |  * - File picker nativo para abrir arquivos de áudio
  6 |  * - Notificações do sistema
  7 |  * - Atalhos de teclado globais
  8 |  * - Informações do sistema
  9 |  */
 10 | 
 11 | import { useState, useCallback, useEffect, useRef } from "react";
 12 | 
 13 | // Detecta se está rodando dentro do Tauri
 14 | function isTauri(): boolean {
 15 |   return typeof window !== "undefined" && "__TAURI_INTERNALS__" in window;
 16 | }
 17 | 
 18 | export interface TauriState {
 19 |   isTauri: boolean;
 20 |   isReady: boolean;
 21 |   musicDir: string | null;
 22 |   systemInfo: Record<string, string> | null;
 23 | }
 24 | 
 25 | /**
 26 |  * Hook para funcionalidades nativas do Tauri.
 27 |  * Fornece fallback para navegador quando não está em ambiente Tauri.
 28 |  */
 29 | export function useTauri() {
 30 |   const [state, setState] = useState<TauriState>({
 31 |     isTauri: isTauri(),
 32 |     isReady: false,
 33 |     musicDir: null,
 34 |     systemInfo: null,
 35 |   });
 36 |   const initialized = useRef(false);
 37 | 
 38 |   useEffect(() => {
 39 |     if (initialized.current) return;
 40 |     initialized.current = true;
 41 | 
 42 |     if (!isTauri()) return;
 43 | 
 44 |     const init = async () => {
 45 |       try {
 46 |         const { invoke } = await import("@tauri-apps/api/core");
 47 | 
 48 |         const [musicDir, systemInfo] = await Promise.all([
 49 |           invoke<string>("get_music_dir").catch(() => null),
 50 |           invoke<Record<string, string>>("get_system_info").catch(() => null),
 51 |         ]);
 52 | 
 53 |         setState({
 54 |           isTauri: true,
 55 |           isReady: true,
 56 |           musicDir,
 57 |           systemInfo,
 58 |         });
 59 |       } catch (err) {
 60 |         console.warn("[Llama Player] Erro ao inicializar Tauri:", err);
 61 |         setState((prev) => ({ ...prev, isReady: true }));
 62 |       }
 63 |     };
 64 | 
 65 |     init();
 66 |   }, []);
 67 | 
 68 |   /**
 69 |    * Abre o file picker nativo do sistema para selecionar arquivos de áudio.
 70 |    * Retorna os caminhos dos arquivos selecionados.
 71 |    */
 72 |   const openFilePicker = useCallback(async (): Promise<string[] | null> => {
 73 |     if (!isTauri()) {
 74 |       // Fallback: dispara input file HTML (para desenvolvimento web)
 75 |       return new Promise((resolve) => {
 76 |         const input = document.createElement("input");
 77 |         input.type = "file";
 78 |         input.accept = "audio/*";
 79 |         input.multiple = true;
 80 |         input.onchange = () => {
 81 |           if (input.files) {
 82 |             const paths = Array.from(input.files).map((f) => f.name);
 83 |             resolve(paths);
 84 |           } else {
 85 |             resolve(null);
 86 |           }
 87 |         };
 88 |         input.click();
 89 |       });
 90 |     }
 91 | 
 92 |     try {
 93 |       const dialog = await import("@tauri-apps/plugin-dialog");
 94 | 
 95 |       const selected = await dialog.open({
 96 |         multiple: true,
 97 |         filters: [
 98 |           {
 99 |             name: "Áudio",
100 |             extensions: [
101 |               "mp3",
102 |               "wav",
103 |               "flac",
104 |               "ogg",
105 |               "aac",
106 |               "m4a",
107 |               "wma",
108 |               "opus",
109 |             ],
110 |           },
111 |         ],
112 |       });
113 | 
114 |       if (!selected) return null;
115 | 
116 |       const paths = Array.isArray(selected) ? selected : [selected];
117 |       return paths;
118 |     } catch (err) {
119 |       console.error("[Llama Player] Erro no file picker nativo:", err);
120 |       return null;
121 |     }
122 |   }, []);
123 | 
124 |   /**
125 |    * Converte um caminho de arquivo local para URL acessível pelo frontend.
126 |    */
127 |   const filePathToUrl = useCallback(async (path: string): Promise<string> => {
128 |     if (!isTauri()) return path;
129 | 
130 |     try {
131 |       const { convertFileSrc } = await import("@tauri-apps/api/core");
132 |       return convertFileSrc(path);
133 |     } catch {
134 |       return path;
135 |     }
136 |   }, []);
137 | 
138 |   /**
139 |    * Envia uma notificação do sistema.
140 |    */
141 |   const sendNotification = useCallback(
142 |     async (title: string, body?: string) => {
143 |       if (!isTauri()) {
144 |         // Fallback: Notification API do navegador
145 |         if ("Notification" in window && Notification.permission === "granted") {
146 |           new Notification(title, { body });
147 |         } else if ("Notification" in window) {
148 |           const permission = await Notification.requestPermission();
149 |           if (permission === "granted") {
150 |             new Notification(title, { body });
151 |           }
152 |         }
153 |         return;
154 |       }
155 | 
156 |       try {
157 |         const notification = await import("@tauri-apps/plugin-notification");
158 |         notification.sendNotification({ title, body });
159 |       } catch (err) {
160 |         console.warn("[Llama Player] Erro ao enviar notificação:", err);
161 |       }
162 |     },
163 |     []
164 |   );
165 | 
166 |   /**
167 |    * Registra atalhos de teclado globais.
168 |    * Retorna função de cleanup.
169 |    */
170 |   const registerShortcuts = useCallback(
171 |     async (
172 |       shortcuts: Record<string, () => void>
173 |     ): Promise<() => void> => {
174 |       if (!isTauri()) {
175 |         // Fallback: atalhos locais (keydown)
176 |         const handler = (e: KeyboardEvent) => {
177 |           // Media keys
178 |           if (e.code === "MediaPlayPause") shortcuts["MediaPlayPause"]?.();
179 |           if (e.code === "MediaNextTrack") shortcuts["MediaNextTrack"]?.();
180 |           if (e.code === "MediaPrevTrack") shortcuts["MediaPrevTrack"]?.();
181 |           if (e.code === "MediaStop") shortcuts["MediaStop"]?.();
182 |         };
183 |         window.addEventListener("keydown", handler);
184 |         return () => window.removeEventListener("keydown", handler);
185 |       }
186 | 
187 |       try {
188 |         const shortcutPlugin = await import("@tauri-apps/plugin-global-shortcut");
189 | 
190 |         const registrations = Object.entries(shortcuts).map(
191 |           ([shortcut, handler]) =>
192 |             shortcutPlugin.register(shortcut, () => handler()).catch((err: any) =>
193 |               console.warn(
194 |                 `[Llama Player] Erro ao registrar atalho ${shortcut}:`,
195 |                 err
196 |               )
197 |             )
198 |         );
199 | 
200 |         await Promise.all(registrations);
201 | 
202 |         return async () => {
203 |           await Promise.all(
204 |             Object.keys(shortcuts).map((s) =>
205 |               shortcutPlugin.unregister(s).catch(() => {})
206 |             )
207 |           );
208 |         };
209 |       } catch (err) {
210 |         console.warn("[Llama Player] Erro ao registrar atalhos:", err);
211 |         return () => {};
212 |       }
213 |     },
214 |     []
215 |   );
216 | 
217 |   /**
218 |    * Abre uma URL no navegador padrão do sistema.
219 |    */
220 |   const openUrl = useCallback(async (url: string) => {
221 |     if (!isTauri()) {
222 |       window.open(url, "_blank");
223 |       return;
224 |     }
225 | 
226 |     try {
227 |       const shell = await import("@tauri-apps/plugin-shell");
228 |       await shell.open(url);
229 |     } catch (err) {
230 |       console.warn("[Llama Player] Erro ao abrir URL:", err);
231 |       window.open(url, "_blank");
232 |     }
233 |   }, []);
234 | 
235 |   return {
236 |     state,
237 |     openFilePicker,
238 |     filePathToUrl,
239 |     sendNotification,
240 |     registerShortcuts,
241 |     openUrl,
242 |     isTauri: isTauri(),
243 |   };
244 | }
